      const x = (clientX - box.left) / box.width - 0.5;
      const y = (clientY - box.top) / box.height - 0.5;
      projectVisual.style.setProperty("--tilt-x", `${(-y * 5).toFixed(2)}deg`);
      projectVisual.style.setProperty("--tilt-y", `${(x * 6).toFixed(2)}deg`);
